u.E("ev-sentenza-29-1995",1995,"1995","Sentenza n. 29/1995 sui presupposti del decreto-legge","La Corte afferma di poter controllare necessità e urgenza e che il vizio si trasmette alla legge di conversione.","giurisprudenza","decreto-legge legge-di-conversione",130,130)
u.E("ev-sentenza-360-1996",1996,"24 ottobre 1996","Sentenza n. 360/1996 sulla reiterazione","La Corte dichiara illegittima la reiterazione dei decreti-legge non convertiti.","giurisprudenza","reiterazione-decreti-legge",130,130)
u.E("ev-sentenza-171-2007",2007,"2007","Sentenza n. 171/2007 sull'evidente carenza dei presupposti","Prima dichiarazione di illegittimità di un decreto-legge convertito per evidente mancanza di necessità e urgenza.","giurisprudenza","decreto-legge",130,130)
u.E("ev-rifiuto-napolitano-2009",2009,"6 febbraio 2009","Rifiuto di emanare il decreto-legge sul caso Englaro","Il Presidente Napolitano rifiuta di emanare un decreto-legge per evidente mancanza dei presupposti e per i dubbi di costituzionalità.","politica","decreto-legge presidente-della-repubblica",131,131)
u.E("ev-sentenza-22-2012",2012,"2012","Sentenza n. 22/2012 sull'omogeneità della conversione","La Corte vieta di inserire nella legge di conversione emendamenti estranei all'oggetto del decreto.","giurisprudenza","omogeneita-decreto-legge legge-di-conversione",132,132)
u.E("ev-legge-bassanini",1997,"15 marzo 1997","Legge n. 59/1997 (Bassanini)","Tra l'altro introduce la riserva di regolamento sugli uffici dei ministeri e la legge annuale di semplificazione.","legge","riserva-di-regolamento",137,137)
u.E("ev-legge-costituzionale-1-1989",1989,"16 gennaio 1989","Legge costituzionale n. 1/1989 sui reati ministeriali","Riscrive l'art. 96: i ministri sono giudicati dalla giurisdizione ordinaria, previa autorizzazione della Camera.","legge","reati-ministeriali",142,143)
u.E("ev-legge-cnel-1957",1957,"5 gennaio 1957","Legge n. 33/1957 istitutiva del CNEL","Dà attuazione all'art. 99 della Costituzione.","legge","cnel",143,143)
u.E("ev-legge-cnel-1986",1986,"30 dicembre 1986","Legge n. 936/1986 sul CNEL","Riforma il CNEL, ne aumenta i componenti e ne amplia le attribuzioni.","legge","cnel",143,143)
u.E("ev-crisi-prodi-1998",1998,"9 ottobre 1998","Caduta del I governo Prodi","La Camera respinge la questione di fiducia: crisi parlamentare.","politica","crisi-di-governo",141,141)
u.E("ev-crisi-prodi-2008",2008,"24 gennaio 2008","Caduta del II governo Prodi","Il Senato nega la fiducia: crisi parlamentare che porta allo scioglimento anticipato.","politica","crisi-di-governo",141,141)

